import "dotenv/config";
import { createDailyBriefingTracerFromEnv, resolveTracingProvider } from "../src/observability/create-tracer-from-env.js";

const COUNT = Number(process.env.TRACE_GEN_COUNT ?? "110");
const BATCH_FLUSH = 25;

async function main(): Promise<void> {
  const provider = resolveTracingProvider(process.env);
  if (provider === "noop") {
    console.error("TRACING_PROVIDER is noop — set braintrust credentials first");
    process.exit(1);
  }

  const tracer = createDailyBriefingTracerFromEnv();
  console.log(`generating ${COUNT} traces via ${provider}...`);

  for (let i = 0; i < COUNT; i++) {
    const day = String((i % 28) + 1).padStart(2, "0");
    const trace = tracer.startTrace({
      briefingDate: `2026-06-${day}`,
      inputDir: "inputs",
      model: "trace-generator",
      maxRevisions: 1,
    });

    const run = trace.startAgentRun({
      kind: i % 3 === 0 ? "revision" : "initial",
      attempt: (i % 3) + 1,
      prompt: `Synthetic briefing run #${i + 1}`,
      agentId: "trace-generator",
      model: "trace-generator",
    });

    trace.recordValidationAttempt({
      attempt: 1,
      issueCount: i % 5,
      issues: [],
    });

    trace.recordFinalResult({
      outline: { sections: [{ title: `Section ${i}`, bullets: ["a", "b"] }] },
      draft: `Synthetic draft for trace ${i + 1}.`,
      revisionCount: i % 3,
    });

    run.end();
    trace.end();

    if ((i + 1) % BATCH_FLUSH === 0) {
      await tracer.flush();
      console.log(`  flushed ${i + 1}/${COUNT}`);
    }
  }

  await tracer.flush();
  await tracer.shutdown?.();
  console.log(`done: generated ${COUNT} root traces`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

