for (let i = 0; i < 100; i++) {
  const base = SCENARIOS[i % SCENARIOS.length]!;
  const category = categoryVariants[i % categoryVariants.length]!;
  const day = String((i % 28) + 1).padStart(2, "0");
  ALL_SCENARIOS.push({
    ...base,
    date: `2026-05-${day}`,
    category,
    prompt: `${base.prompt} [session ${i + 1}, focus: ${category.replace(/_/g, " ")}]`,
    payload: varyPayload(base.payload, i, category),
    validationIssues: i % 7 === 0 ? base.validationIssues : i % 11 === 0 ? warningOnly(i) : [],
    revisionCount: i % 4,
    toolError: i % 13 === 0,
    runError: i % 23 === 0,
  });
}

async function main(): Promise<void> {
  if (resolveTracingProvider(process.env) === "noop") {
    console.error("Configure TRACING_PROVIDER=braintrust first");
    process.exit(1);
  }

  const tracer = createDailyBriefingTracerFromEnv();
  console.log(`exporting ${ALL_SCENARIOS.length} production-like traces...`);

  for (let i = 0; i < ALL_SCENARIOS.length; i++) {
    const scenario = ALL_SCENARIOS[i]!;
    const trace = tracer.startTrace({
      briefingDate: scenario.date,
      inputDir: "inputs",
      model: "claude-4-sonnet",
      maxRevisions: 2,
    });

    trace.recordSourceProcessing(scenario.sourceSummary);

    const run = trace.startAgentRun({
      kind: scenario.revisionCount > 0 ? "revision" : "initial",
      attempt: scenario.revisionCount + 1,
      prompt: scenario.prompt,
      agentId: "daily-briefing-agent",
      model: "claude-4-sonnet",
    });

    emitToolCalls(run, scenario, i);

    if (scenario.runError) {
      run.recordError(new Error("Cursor SDK run timed out after 120s waiting for agent JSON output"));
      trace.recordError(new Error("Briefing generation failed — no valid outline/draft returned"));
    } else {
      run.recordRunResult({
        id: `run-${scenario.date}-${i}`,
        status: "completed",
        result: JSON.stringify(scenario.payload),
        durationMs: 45_000 + (i % 30) * 1000,
      } as RunResult);
      run.recordParsedPayload(scenario.payload);
    }

    for (let attempt = 1; attempt <= Math.max(1, scenario.revisionCount + 1); attempt++) {
      const issues = attempt === Math.max(1, scenario.revisionCount + 1) ? scenario.validationIssues : scenario.validationIssues.slice(0, 1);
      trace.recordValidationAttempt({
        attempt,
        issueCount: issues.length,
        issues,
      });
    }

    if (!scenario.runError) {
      trace.recordFinalResult({
        outline: scenario.payload.outline,
        draft: scenario.payload.draft,
        revisionCount: scenario.revisionCount,
      });
    }

    run.end();
    trace.end();

    if ((i + 1) % 10 === 0) {
      await tracer.flush();
      console.log(`  ${i + 1}/${ALL_SCENARIOS.length}`);
    }
  }

  await tracer.flush();
  await tracer.shutdown?.();
  console.log("done");
}

function emitToolCalls(run: ReturnType<ReturnType<typeof tracerStart>["startAgentRun"]>, scenario: Scenario, index: number): void {
  const searchEvent = {
    type: "tool_call",
    name: "mcp",
    call_id: `search-${index}`,
    run_id: `run-${index}`,
    status: scenario.toolError ? "error" : "completed",
    args: {
      providerIdentifier: "daily-briefing-sources",
      toolName: "candidate_search",
      query: scenario.category,
    },
    result: scenario.toolError
      ? { error: "MCP server timeout after 30s" }
      : { candidates: scenario.sourceSummary.totals.candidateCount, category: scenario.category },
    truncated: false,
  } as SDKMessage;
  run.recordStreamEvent(searchEvent);

  run.recordStreamEvent({
    type: "assistant",
    message: { role: "assistant", content: [{ type: "text", text: scenario.payload.draft.finalTtsText.slice(0, 500) }] },
  } as SDKMessage);
}

function tracerStart(input: Parameters<ReturnType<typeof createDailyBriefingTracerFromEnv>["startTrace"]>[0]) {
  return createDailyBriefingTracerFromEnv().startTrace(input);
}

