interface PayloadInput {
  opening: string;
  sections: Array<{ title: string; text: string }>;
  themes: string[];
  mustInclude: string[];
  excluded: Array<{ id: string; reason: string }>;
}

function makePayload(input: PayloadInput): AgentRunPayload {
  const sectionBodies = input.sections.map((s, idx) => ({
    sectionId: `section-${idx + 1}`,
    title: s.title,
    text: s.text,
    candidateIds: input.mustInclude.slice(idx, idx + 2),
  }));
  const fullText = sectionBodies.map((s) => `[${s.title}] ${s.text}`).join("\n\n");
  const finalTts = `${input.opening} ${sectionBodies.map((s) => s.text).join(" ")}`.replace(/\s+/g, " ").trim();
  return {
    outline: {
      themes: input.themes.map((theme, idx) => ({
        id: `theme-${idx + 1}`,
        topicTags: [theme as never],
        candidateIds: input.mustInclude.slice(0, 3),
        reason: `Theme: ${theme.replace(/_/g, " ")}`,
      })),
      sections: sectionBodies.map((s, idx) => ({
        id: s.sectionId,
        name: s.title,
        candidateIds: s.candidateIds,
        coveredInputItemIds: { calendar: [], emails: [], news: [] },
        targetWords: 80 + idx * 20,
      })),
      mustIncludeCandidateIds: input.mustInclude,
      excludedCandidateIds: input.excluded,
      discardedInputItems: input.excluded.map((e) => ({
        id: e.id,
        sourceType: e.id.startsWith("cal_") ? "calendar" : e.id.startsWith("em_") ? "email" : "news",
        reason: e.reason,
      })),
      explorationReasoning: [
        `Prioritized ${input.themes[0]?.replace(/_/g, " ") ?? "schedule"} given user profile and today's calendar density.`,
        "Filtered sports and entertainment per not_interested rules.",
      ],
    },
    draft: {
      sections: sectionBodies,
      fullTextWithSectionMarkers: fullText,
      finalTtsText: padToBriefingLength(finalTts),
    },
  };
}

function padToBriefingLength(text: string): string {
  const filler =
    " Before you head out, remember the briefing is tuned for audio — numbers are spoken naturally and private calendar details stay out unless you need them for decisions today.";
  let result = text;
  while (result.split(/\s+/).length < 135) {
    result += filler;
  }
  return result;
}

function varyPayload(base: AgentRunPayload, index: number, category: string): AgentRunPayload {
  const focusLine = categoryFocusLine(category, index);
  return {
    ...base,
    draft: {
      ...base.draft,
      finalTtsText: padToBriefingLength(`${focusLine} ${base.draft.finalTtsText}`),
      sections: base.draft.sections.map((section, idx) => ({
        ...section,
        text: idx === 0 ? `${section.text} (${category.replace(/_/g, " ")}, run ${index + 1})` : section.text,
      })),
    },
    outline: {
      ...base.outline,
      explorationReasoning: [
        ...base.outline.explorationReasoning,
        `Session ${index + 1}: emphasized ${category.replace(/_/g, " ")} for Topics clustering.`,
      ],
    },
  };
}

function categoryFocusLine(category: string, index: number): string {
  const lines: Record<string, string[]> = {
    schedule_conflict: [
      "First up — you have overlapping commitments this afternoon that need a decision before standup ends.",
      "Heads up on a calendar collision that affects both family and customer time blocks.",
